(function () {
var username = String(global.creator_username || '').trim().replace(/^wxchannels:/, '');
if (!username || username.indexOf('REPLACE_') >= 0) throw new Error('请先配置创作者 username');
if (!/@finder$/.test(username)) username += '@finder';
if (!(global.max_pages > 0) || !(global.max_videos > 0)) throw new Error('max_pages 和 max_videos 必须大于 0');
if (!global.monitor_schedule_id || String(global.monitor_schedule_id).indexOf('REPLACE_') >= 0) throw new Error('请先配置本 Pipeline 的定时规则 ID');
return {username: username};
})()

(function () {
var response = output.load_schedule.schedule_response;
if (output.load_schedule.schedule_response_status !== 200 || !response || response.code !== 0 || !response.data) throw new Error('读取定时规则失败');
var schedule = response.data;
if (schedule.id !== global.monitor_schedule_id) throw new Error('定时规则 ID 不匹配');
var initial_data = schedule.initial_data || {};
if (typeof initial_data === 'string') initial_data = JSON.parse(initial_data || '{}');
var previous = initial_data.creator_video_monitor;
if (previous && previous.username === output.validate.creator.username && (!Array.isArray(previous.known_ids) || previous.initialized !== true)) throw new Error('监控基线损坏，请检查定时规则 initial_data');
if (!previous || previous.username !== output.validate.creator.username) previous = {username:output.validate.creator.username,initialized:false,known_ids:[]};
return {initial_data:initial_data,previous:previous};
})()

(function () {
var response = output.fetch_page.page_result;
if (!response || (response.errCode !== undefined && Number(response.errCode) !== 0) || (response.code !== undefined && Number(response.code) !== 0)) throw new Error('获取视频列表失败');
var data = response.data;
if (!data || !Array.isArray(data.object)) throw new Error('视频列表响应缺少 data.object');
if (data.BaseResponse && Number(data.BaseResponse.ret || 0) !== 0) throw new Error('视频列表 BaseResponse 返回错误');
if (data.continueFlag === undefined) throw new Error('视频列表缺少 continueFlag，无法确认是否已获取全部视频');
var state = JSON.parse(JSON.stringify(global.scan_state));
state.page += 1;
if (state.page > global.max_pages) throw new Error('超过 max_pages，本次同步未完成，请调大限制');
state.items = []; state.index = 0;
function id_string(value) {
  if (typeof value === 'number' && (!isFinite(value) || Math.floor(value) !== value || Math.abs(value) > 9007199254740991)) throw new Error('平台返回不安全的数字 ID，需要字符串 ID');
  return value === undefined || value === null ? '' : String(value);
}
for (var i = 0; i < data.object.length; i++) {
  var item = data.object[i], desc = item.objectDesc || {}, media = desc.media || [];
  if (Number(desc.mediaType) !== 4 && !media.some(function (m) { return Number(m.mediaType) === 4; })) continue;
  var oid = id_string(item.id), nid = id_string(item.objectNonceId);
  if (!oid || !nid) throw new Error('视频缺少 id 或 objectNonceId');
  if (state.seen_ids[oid]) continue;
  state.seen_ids[oid] = true;
  if (Object.keys(state.seen_ids).length > global.max_videos) throw new Error('超过 max_videos，本次扫描未完成');
  state.items.push({oid:oid,nid:nid,title:String(desc.description || ''),published_at:item.createtime || item.createTime || 0});
}
state.has_more = Number(data.continueFlag) !== 0;
state.next_cursor = data.lastBuffer || '';
if (state.has_more) {
  if (typeof state.next_cursor !== 'string' || !state.next_cursor || state.next_cursor === state.cursor || state.visited_cursors.indexOf(state.next_cursor) >= 0) throw new Error('分页游标缺失或重复，停止以避免漏数据或无限循环');
  if (state.page >= global.max_pages) throw new Error('达到 max_pages 但仍有下一页，本次扫描未完成');
}
return state;
})()

(function () {
var state = JSON.parse(JSON.stringify(global.scan_state));
state.videos = state.videos.concat(state.items);
return state;
})()

(function () {
var state = JSON.parse(JSON.stringify(global.scan_state));
state.visited_cursors.push(state.next_cursor); state.cursor = state.next_cursor;
return state;
})()

(function () {
var baseline = output.load_baseline.baseline, previous = baseline.previous;
var known = {}; previous.known_ids.forEach(function (id) { known[String(id)] = true; });
var pending = global.scan_state.videos.filter(function (video) { return !known[video.oid]; });
if (!previous.initialized) {
  global.scan_state.videos.forEach(function (video) { known[video.oid] = true; }); pending = [];
}
return {initial_data:baseline.initial_data,known_ids:Object.keys(known),pending:pending,index:0,checkpoint_saved:false,baseline_created:!previous.initialized};
})()

(function () {
var video = global.notification_state.pending[global.notification_state.index];
return {msgtype:'text',text:{content:'创作者发布了新视频
账号：' + output.validate.creator.username + '
标题：' + video.title.slice(0, 1500) + '
视频 ID：' + video.oid + '
发布时间：' + String(video.published_at)}};
})()

(function () {
var response = output.notify.webhook_response;
if (output.notify.webhook_response_status !== 200 || !response || Number(response.errcode) !== 0) throw new Error('企业微信通知失败，保留未通知状态以便下次重试');
var state = JSON.parse(JSON.stringify(global.notification_state));
state.known_ids.push(state.pending[state.index].oid); state.index += 1; state.checkpoint_saved = false;
return state;
})()

(function () {
var state = global.notification_state;
var initial_data = JSON.parse(JSON.stringify(state.initial_data));
initial_data.creator_video_monitor = {username:output.validate.creator.username,initialized:true,known_ids:state.known_ids};
return {id:global.monitor_schedule_id,initial_data:initial_data};
})()

(function () {
var response = output.save_checkpoint.checkpoint_response;
if (output.save_checkpoint.checkpoint_response_status !== 200 || !response || response.code !== 0) throw new Error('通知进度保存失败，下次可能重复通知');
var state = JSON.parse(JSON.stringify(global.notification_state)); state.checkpoint_saved = true;
return state;
})()
